from s114_course_common import teach
S='objective-refraction-p1'
teach(S,'setup-1',[
(0,'病人看遠目標，你看瞳孔反光','兩個人正在看不同的東西。',[('病人注視','遠方較大的視標，盡量放鬆調節'),('檢查者觀察','從觀察孔看眼底回光'),('稍離視線','讓病人仍能看到遠目標，又避免過度離軸')],'調節是眼睛主動增加收光力，可能讓結果偏近視；不是瞳孔一小就代表完全放鬆。'),
(2,'固定位置才知道要扣幾D','工作距離改了，補償也會改。',[('50cm','WL＝1/0.50＝2.00D'),('67cm','近似WL＝1.50D'),('淨值','含全部中和鏡的毛值−WL')],'手臂或量距工具只是幫忙固定；若讀值已排除另放的WL，不再重複扣。'),
(4,'套筒有兩個動作：上下調光、旋轉方向','先辨實際平面鏡效應，再用順逆動口訣。',[('平面鏡效應','常用發散光，順動加正、逆動加負'),('凹面鏡效應','動向相反，不能沿用同口訣'),('上下位置','不同檢影鏡設計可能不同，以下為課堂機型')],'轉套筒換光帶方向，和上下推套筒改聚散，不要混成同一操作。')])
teach(S,'motion-neutral-1',[
(0,'跟著掃動走，才叫順動','比較對象是瞳孔回光和你掃光的方向。',[('With','同方向'),('Against','反方向'),('Neutral','遠點對到觀察位置，整瞳孔亮、難見方向移動')],'以下先固定平面鏡效應與工作距離，改鏡片去找中和。'),
(2,'夾逼：確認中和點在兩種動向中間','不是看起來很亮，就一定已中和。',[('從順動加正','接近中和後，再加可跨成逆動'),('退一小步','縮小順／逆切換的區間'),('觀察條件','工作距離、調節、掃動方向都要穩定')],'若往錯方向加鏡，反光可能變慢變暗；先回查設定，不只繼續堆鏡。'),
(4,'球鏡定共同力量，負柱鏡再補另一方向','先說中和的是屈光方向，不是光帶長軸。',[('較正方向先中和','用S設定第一個主方向'),('另一方向','光帶轉90°觀察，若需更負用C補'),('負柱鏡軸','放在第一個不需要再加C的主方向')],'轉光帶觀察另一方向，不表示任何時候都把已設定的柱鏡軸一起轉；軸由要保留的S方向決定。')])
teach(S,'phoropter-cylinder-1',[
(0,'S、C、軸：三個旋鈕做不同事','S改兩方向共同值；C改方向差；軸把C轉到該去的位置。',[('S sphere','球鏡；各方向加相同D'),('C cylinder','柱鏡；軸上不額外加力，垂直軸加完整C'),('Axis','柱鏡軸，以°記，不是D')],'可先用光十字畫出想補的兩方向，再決定旋鈕。'),
(2,'投光條與回光條平行，是對齊線索','光帶方向與該次量的屈光方向差90°。',[('垂直光帶左右掃','測水平屈光方向'),('負柱鏡中和第二方向','柱鏡軸常與這次光帶平行，讓負力作用於掃動方向'),('回查第一方向','轉光帶檢查，柱鏡軸不應無理由跟著改')],'「三平行」要放在課堂負柱鏡操作的對應步驟讀，不是所有中和時刻都強求三者平行。'),
(4,'兩個淨度數，負散球面取較正','先確認工作距離已扣完。',[('−1.75與+0.50','較正是+0.50，當S'),('C','−1.75−(+0.50)＝−2.25D'),('軸','沿+0.50那個屈光方向，仍需題目提供方向')],'只給兩個D沒有方向，不能唯一填完整軸位。')])
teach(S,'review-cases-1',[
(0,'讀值包含了哪些鏡片？先列出來','不是看到「輔助鏡」三字就自動不扣。',[('毛值含WL','扣一次WL'),('另放WL、讀數已排除它','不再扣'),('舊眼鏡或隱形眼鏡','還要分這次是追加量，還是全度數')],'同一個人的淨度數固定；站近或站遠改變的是中和毛值與WL。'),
(2,'160°的光帶，掃的是70°方向','一條長線的朝向，和它橫掃過去的方向不同。',[('光帶160°','長條光本身的方向'),('垂直方向','160−90＝70°，該次量的主方向'),('怎麼記軸','先記光十字的屈光方向，再轉S/C/axis')],'不能把題目說的所有角度一律抄到處方軸欄。'),
(4,'客觀結果是起點，最後還要確認看得如何','量到幾D與適合配幾D，不是永遠同一句話。',[('檢影','從反光得到起始估值'),('回查兩眼','注意調節、定位或操作變化'),('主觀微調','能配合者比較清晰舒適，確認視力')],'不能因病人不易回答就省略結果合理性與眼部健康的評估。')])
